from math import gcd
from typing import List

def lcm(a, b):
    return a * b // gcd(a, b)

class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        t = len(target)
        full = (1 << t) - 1

        # Precompute lcm for all subsets of targets, use as mask
        lcms = [1] * (1 << t)
        for mask in range(1, 1 << t):
            l = 1
            for i in range(t):
                if (mask >> i) & 1:
                    l = lcm(l, target[i])
            lcms[mask] = l

        INF = float('inf')
        # f[mask] = min total cost to cover the targets in mask using the elements processed so far
        f = [INF] * (1 << t)
        f[0] = 0
        for x in nums:
            # cost for this element to become a multiple of lcms[s] (next multiple >= x)
            cost = [(-x) % lcms[s] for s in range(1 << t)]
            new_f = f[:]  # each element is used at most once (it may also be unused)
            for mask in range(1 << t):
                if f[mask] == INF:
                    continue
                rest = full ^ mask
                s = rest
                while s:
                    v = f[mask] + cost[s]
                    if v < new_f[mask | s]:
                        new_f[mask | s] = v
                    s = (s - 1) & rest
            f = new_f
        return f[full]
